  {target:"Financial planning", c:"fplan", sents:["Arya Hospitals plans to open four new centres.","Its finance team made a chart of how much money is needed each quarter for three years and where it will come from.","The centres will have 200 beds each.","The doctors are highly qualified."], a:1, why:"A blueprint of fund needs and sources: <b>financial planning</b>."},
  {target:"Credit allowed (working capital)", c:"wc", sents:["Om Steel sells to builders.","To win orders, it lets builders pay after 120 days.","Its plant runs day and night.","It exports to Nepal."], a:1, why:"Long credit to customers: <b>credit allowed</b>, which raises working capital."},
  {target:"Control considerations (financing)", c:"fin", sents:["Saxena Foods is owned by one family.","It needs ₹30 crore for a new plant.","The family decided on a bank loan, refusing to issue shares to the public so that outsiders do not get voting rights.","The plant will make biscuits."], a:2, why:"Avoiding equity to keep control: <b>control considerations</b>."}
